import SwiftUI

/// 剪贴板列表行视图（预览扩展）
///
/// 职责扩展：
/// - 检测鼠标悬停事件
/// - 通知 ViewModel 悬停状态变化
/// - 管理悬停定时器
///
/// 依赖：
/// - ClipboardHistoryViewModel: 接收悬停事件
extension ClipboardItemRowView {

    /// 悬停检测修饰符（添加到现有视图）
    func previewHoverDetection(item: ClipboardItem, viewModel: ClipboardHistoryViewModel) -> some View {
        self.onHover { isHovering in
            if isHovering {
                viewModel.onItemHovered(item)
            } else {
                viewModel.onItemExited()
            }
        }
    }
}

