// MARK: - Focus Management Extension

extension ClipboardItemRowView {

    /// 焦点绑定（用于键盘导航）
    func focusManagement(isFocused: Binding<Bool>, item: ClipboardItem, viewModel: ClipboardHistoryViewModel) -> some View {
        self
            .focused($isFocused.wrappedValue)
            .onChange(of: isFocused.wrappedValue) { _, newValue in
                if newValue {
                    viewModel.onItemFocused(item)
                }
            }
    }
}

// MARK: - Hover State Tracking

/// 悬停状态跟踪器（可选的独立组件）
@Observable
class HoverStateTracker {
    var currentHoveredItem: ClipboardItem?
    var hoverStartTime: Date?

    private var hoverTimer: Timer?

    /// 开始悬停计时
    func startHover(for item: ClipboardItem, delay: TimeInterval = 0.2, completion: @escaping () -> Void) {
        currentHoveredItem = item
        hoverStartTime = Date()

        hoverTimer?.invalidate()
        hoverTimer = Timer.scheduledTimer(withTimeInterval: delay, repeats: false) { [weak self] _ in
            if self?.currentHoveredItem?.id == item.id {
                completion()
            }
        }
    }

    /// 取消悬停
    func cancelHover() {
        hoverTimer?.invalidate()
        hoverTimer = nil
        currentHoveredItem = nil
        hoverStartTime = nil
    }

    /// 是否正在悬停
    var isHovering: Bool {
        currentHoveredItem != nil
    }
}
